import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.for-each.js";
import "core-js/modules/es.iterator.some.js";
import CountryList from "@/JsonFiles/CountryList.json";
import { get_all_org_users } from "@/mixins/GetUsersDropdown.js";
export default {
  mixins: [get_all_org_users],
  data() {
    return {
      roleItems: ["Member", "Observer"],
      projectManagerDisplay: "",
      memberType: "INTERNAL",
      internalTeamMember: {
        full_user_name: "",
        userRole: ""
      },
      externalTeamMember: {
        userName: "",
        userEmail: "",
        countryCode: "+91",
        contactNumber: ""
      },
      teamMembers: [],
      userArray: [],
      countryitems: [],
      rules: {
        required: v => !!v || "Field is required",
        email: v => /.+@.+\..+/.test(v) || "E-mail must be valid",
        phoneNumber: v => /^(\+\d{1,3}[- ]?)?\d{10}$/.test(v) || "Phone number must be valid"
      }
    };
  },
  async mounted() {
    this.projectManagerDisplay = this.$store.getters.GetUserObj.user.full_user_name;
    await this.get_all_org_users();
    this.fetchDetails();
  },
  methods: {
    is_number(evt, value) {
      evt = evt || window.event;
      var charCode = evt.which ? evt.which : evt.keyCode;
      if (charCode > 31 && (charCode < 48 || charCode > 57) && charCode !== 46) {
        evt.preventDefault();
      }
      if (value.length >= 14 && charCode >= 48 && charCode <= 57) {
        evt.preventDefault();
      }
    },
    fetchDetails() {
      this.orgUsers.forEach(element => {
        if (element.user_status == "ACTIVE") {
          if (element.user_email_id != this.$store.getters.GetUserObj.user.user_email_id) {
            this.userArray.push({
              full_user_name: element.full_user_name,
              user_email_id: element.user_email_id,
              user_country_code: element.user_country_code,
              user_contact_number: element.user_contact_number
            });
          }
        }
      });
      CountryList.forEach(element => {
        this.countryitems.push({
          name: element.dial_code + "(" + element.name + ")",
          code: element.dial_code
        });
      });
    },
    addTeamMember() {
      if (this.memberType === "INTERNAL" && this.validateInternalMember()) {
        let data = {
          userName: this.internalTeamMember.full_user_name.full_user_name,
          userEmail: this.internalTeamMember.full_user_name.user_email_id,
          userRole: this.internalTeamMember.userRole,
          memberType: "INTERNAL",
          countryCode: this.internalTeamMember.full_user_name.user_country_code == "N/A" ? "" : this.internalTeamMember.full_user_name.user_country_code,
          contactNumber: this.internalTeamMember.full_user_name.user_contact_number == "N/A" ? "" : this.internalTeamMember.full_user_name.user_contact_number
        };
        const dataExisits = this.teamMembers.some(currentdata => currentdata.userEmail === data.userEmail);
        if (dataExisits) {
          this.$emit("errorMsg", "User already Exist");
          this.resetInternalMember();
        } else {
          this.teamMembers.push({
            userName: this.internalTeamMember.full_user_name.full_user_name,
            userEmail: this.internalTeamMember.full_user_name.user_email_id,
            userRole: this.internalTeamMember.userRole,
            memberType: "INTERNAL",
            countryCode: this.internalTeamMember.full_user_name.user_country_code == "N/A" ? "" : this.internalTeamMember.full_user_name.user_country_code,
            contactNumber: this.internalTeamMember.full_user_name.user_contact_number == "N/A" ? "" : this.internalTeamMember.full_user_name.user_contact_number
          });
          this.resetInternalMember();
        }
      } else if (this.memberType === "EXTERNAL" && this.validateExternalMember()) {
        let data = {
          userName: this.externalTeamMember.userName,
          userEmail: this.externalTeamMember.userEmail,
          userRole: "",
          memberType: "EXTERNAL",
          countryCode: this.externalTeamMember.countryCode,
          contactNumber: this.externalTeamMember.contactNumber
        };
        const dataExisits = this.teamMembers.some(currentdata => currentdata.userEmail === data.userEmail);
        if (dataExisits) {
          this.$emit("errorMsg", "User already Exist");
          this.resetExternalMember();
        } else {
          this.teamMembers.push({
            userName: this.externalTeamMember.userName,
            userEmail: this.externalTeamMember.userEmail,
            userRole: "",
            memberType: "EXTERNAL",
            countryCode: this.externalTeamMember.countryCode,
            contactNumber: this.externalTeamMember.contactNumber
          });
          this.resetExternalMember();
        }
      }
    },
    validateInternalMember() {
      const {
        full_user_name,
        userRole
      } = this.internalTeamMember;
      if (!full_user_name || !userRole) {
        this.$refs.form.validate();
        return false;
      }
      return true;
    },
    validateExternalMember() {
      const {
        userName,
        userEmail,
        countryCode,
        contactNumber
      } = this.externalTeamMember;
      if (!userName || !userEmail || !countryCode || !contactNumber) {
        this.$refs.form.validate();
        return false;
      }
      return true;
    },
    resetInternalMember() {
      this.internalTeamMember.full_user_name = "";
      this.internalTeamMember.userRole = "";
    },
    resetExternalMember() {
      this.externalTeamMember.userName = "";
      this.externalTeamMember.userEmail = "";
      this.externalTeamMember.countryCode = "+91";
      this.externalTeamMember.contactNumber = "";
    },
    deleteMember(index) {
      this.teamMembers.splice(index, 1);
    },
    backOptions() {
      this.$emit("ClickedBack");
    },
    validateNextRequest() {
      //   console.log(this.teamMembers);
      this.$emit("validateNext", this.teamMembers);
    }
  }
};
